#ifdef HAVE_CONFIG_H
#include "config.h"
#endif

#include <cassert>

#include "framework/ips_action.h"
#include "framework/module.h"
#include "protocols/packet.h"

using namespace snort;

#define action_name "log"
#define action_help \
    "log the current packet"

#define module_name "log"
#define module_help \
    "manage the counters for the log action"

static THREAD_LOCAL struct LogStats
{
    PegCount log;
} log_stats;

const PegInfo log_pegs[] =
{
    { CountType::SUM, "log", "number of packets that matched an IPS log rule" },
    { CountType::END, nullptr, nullptr }
};

//-------------------------------------------------------------------------
class LogAction : public IpsAction
{
public:
    LogAction() : IpsAction(action_name, nullptr) { }

    void exec(Packet*, const ActInfo&) override;
};

void LogAction::exec(Packet* p, const ActInfo& ai)
{
    if ( log_it(ai) )
    {
        log(p, ai);
        ++log_stats.log;
    }
}

//-------------------------------------------------------------------------

class LogActionModule : public Module
{
public:
    LogActionModule() : Module(module_name, module_help)
    { register_action_pegs(module_name, log_pegs); }

    bool stats_are_aggregated() const override
    { return true; }

    void show_stats() override { }

    const PegInfo* get_pegs() const override
    { return log_pegs; }

    PegCount* get_counts() const override
    { return reinterpret_cast<PegCount*>(&log_stats); }
};

//-------------------------------------------------------------------------
static Module* mod_ctor()
{ return new LogActionModule; }

static void mod_dtor(Module* m)
{ delete m; }

static IpsAction* log_ctor(Module*)
{ return new LogAction; }

static void log_dtor(IpsAction* p)
{ delete p; }

static ActionApi log_api
{
    {
        PT_IPS_ACTION,
        sizeof(ActionApi),
        ACTAPI_VERSION,
        0,
        API_RESERVED,
        API_OPTIONS,
        action_name,
        action_help,
        mod_ctor,
        mod_dtor,
    },
    IpsAction::IAP_LOG,
    nullptr,
    nullptr,
    nullptr,
    nullptr,
    log_ctor,
    log_dtor
};

#ifdef BUILDING_SO
SO_PUBLIC const BaseApi* snort_plugins[] =
#else
const BaseApi* act_log[] =
#endif
{
    &log_api.base,
    nullptr
};

set (IPS_ACTION_SOURCES
    actions_module.cc
    actions_module.h
    ips_actions.cc
    ips_actions.h
)

set( PLUGIN_LIST
    act_alert.cc
    act_block.cc
    act_drop.cc
    act_file_id.cc
    act_log.cc
    act_pass.cc
    act_react.cc
    act_reject.cc
    act_replace.cc
    )

if (STATIC_IPS_ACTIONS)
    add_library ( ips_actions OBJECT
        ${IPS_ACTION_SOURCES}
        ${PLUGIN_LIST}
    )

else (STATIC_IPS_ACTIONS)

    add_library ( ips_actions OBJECT
        ${IPS_ACTION_SOURCES}
    )

    add_dynamic_module(act_alert ips_actions act_alert.cc)
    add_dynamic_module(act_block ips_actions act_block.cc)
    add_dynamic_module(act_drop ips_actions act_drop.cc)
    add_dynamic_module(act_file_id ips_actions act_file_id.cc)
    add_dynamic_module(act_log ips_actions act_log.cc)
    add_dynamic_module(act_pass ips_actions act_pass.cc)
    add_dynamic_module(act_react ips_actions act_react.cc)
    add_dynamic_module(act_reject ips_actions act_reject.cc)
    add_dynamic_module(act_replace ips_actions act_replace.cc)

endif (STATIC_IPS_ACTIONS)

