        RuleListNode* node = sc->rule_lists;
        sc->rule_lists = node->next;
        ordered_list = addNodeToOrderedList(ordered_list, node, evalIndex++);
        sc->evalOrder[node->mode] = evalIndex;
    }

    sc->rule_lists = ordered_list;
}

