static Module* mod_ctor()
{ return new HextModule; }

static void mod_dtor(Module* m)
{ delete m; }

static Logger* hext_ctor(Module* mod)
{
    return new HextLogger(static_cast<HextModule*>(mod));
}

static void hext_dtor(Logger* p)
{ delete p; }

